def shortest_path(graph, start, end):
    if start == end: return [start]
    visited = {start}
    parent = {}
    q = deque([start])
    while q:
        node = q.popleft()
        for n in graph[node]:
            if n in visited: continue
            visited.add(n)
            parent[n] = node
            if n == end:
                path = [n]
                while path[-1] != start:
                    path.append(parent[path[-1]])
                return list(reversed(path))
            q.append(n)
    return None

