def sign_jwt(payload: dict, secret: str) -> str:
    header = {'alg': 'HS256', 'typ': 'JWT'}
    def b64(d): return base64.urlsafe_b64encode(json.dumps(d).encode()).rstrip(b'=').decode()
    h, p = b64(header), b64(payload)
    sig = hmac.new(secret.encode(), f'{h}.{p}'.encode(), hashlib.sha256).digest()
    s = base64.urlsafe_b64encode(sig).rstrip(b'=').decode()
    return f'{h}.{p}.{s}'

def verify_jwt(token: str, secret: str) -> dict:
    h, p, s = token.split('.')
    expected = hmac.new(secret.encode(), f'{h}.{p}'.encode(), hashlib.sha256).digest()
    s_padded = s + '=' * (-len(s) % 4)
    actual = base64.urlsafe_b64decode(s_padded)
    if not hmac.compare_digest(expected, actual):
        raise ValueError('bad signature')
    p_padded = p + '=' * (-len(p) % 4)
    return json.loads(base64.urlsafe_b64decode(p_padded))

