def toposort(graph: dict) -> list:
    in_deg = defaultdict(int)
    for u in graph:
        in_deg.setdefault(u, 0)
        for v in graph[u]:
            in_deg[v] += 1
    q = deque([n for n, d in in_deg.items() if d == 0])
    out = []
    while q:
