import asyncio, time

def async_ttl_cache(seconds: float):
    def decorator(fn):
        cache = {}
        async def wrapper(*args):
            now = time.time()
            if args in cache:
                value, expires = cache[args]
                if expires > now: return value
            value = await fn(*args)
            cache[args] = (value, now + seconds)
            return value
        return wrapper
    return decorator

@async_ttl_cache(60)
async def fetch_user(uid):
    return await db.get_user(uid)

import subprocess
def stream_output(cmd: list[str]):
    proc = subprocess.Popen(
        cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
        text=True, bufsize=1,
    )
    try:
        for line in proc.stdout:
            yield line.rstrip('\n')
    finally:
        proc.wait()
        if proc.returncode != 0:
            raise RuntimeError(f'{cmd} failed: {proc.returncode}')

for line in stream_output(['ping', '-c', '3', '8.8.8.8']):
    print(line)
